mapper.select:
select from aps_mps_item m join mst_item i on i.item_id = m.item_id
m.plant_cd = #{plantCd}
order by m.use_yn desc, m.plant_cd, i.item_cd, m.mps_item_id

select 
  from aps_mps_item m join mst_item i on i.item_id = m.item_id

 where m.mps_item_id = #{id}

mapper.update:
update aps_mps_item
   set remark = #{remark}, use_yn = #{useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where mps_item_id = #{id} and row_ver = #{rowVer}

mapper.select:
select x.item_id, x.plan_end, x.remain_qty from (
    select w.item_id, w.plan_end,
           w.plan_qty - coalesce((select sum(r.qty) from prd_receipt r where r.wo_id = w.wo_id), 0) as remain_qty
      from prd_wo w
     where w.plant_cd = #{plantCd} and w.status in ('PLANNED', 'RELEASED', 'IN_PROGRESS') and w.plan_end <= #{last}
       and w.item_id in #{id}
) x
 where x.remain_qty > 0
 order by x.item_id, x.plan_end

select r.item_id, c.bucket_date, c.plan_qty
  from aps_mps_cell c join aps_mps_row r on r.mps_row_id = c.mps_row_id
 where c.mps_id = #{mpsId}

select 
  from aps_mps m
  join sys_plant p on p.plant_cd = m.plant_cd
  left join aps_mps b on b.mps_id = m.base_mps_id
 where m.calculated_at >= #{from} and m.calculated_at < #{to}
   and m.plant_cd = #{plantCd}
 order by m.calculated_at desc, m.mps_id desc
 limit #{limit}

mapper.update:
update aps_mps set status = 'FIRMED', firmed_at = now(), firmed_by = #{by}, row_ver = row_ver + 1, updated_at = now(),
       updated_by = #{by}
 where mps_id = #{id} and row_ver = #{rowVer} and status = 'DRAFT'
